use serde::{Deserialize,Serialize};use sha2::{Digest,Sha256};use std::collections::{BTreeMap,BTreeSet};
#[derive(Deserialize,Clone)]pub struct MemoryRecord{pub id:String,pub text:String,#[serde(default)]pub revision:u64,#[serde(default)]pub created_at:u64,#[serde(default)]pub updated_at:u64,#[serde(default)]pub importance:f64,#[serde(default)]pub expires_at:Option<u64>,#[serde(default)]pub content_sha256:String}
#[derive(Deserialize)]pub struct MemoryRequest{pub records:Vec<MemoryRecord>,pub query:String,#[serde(default)]pub baseline_records:Vec<MemoryRecord>,#[serde(default)]pub now:u64,#[serde(default)]pub ngram_size:usize,#[serde(default)]pub limit:usize,#[serde(default)]pub duplicate_threshold:f64,#[serde(default)]pub half_life_ms:u64,#[serde(default)]pub required_receipt_ids:Vec<String>,#[serde(default)]pub available_receipt_ids:Vec<String>}
#[derive(Serialize)]pub struct MemoryCandidate{pub id:String,pub similarity:f64,pub decayed_score:f64,pub importance:f64,pub revision:u64}
#[derive(Serialize)]pub struct MemoryDuplicate{pub left_id:String,pub right_id:String,pub similarity:f64}
#[derive(Serialize)]pub struct RevisionChange{pub id:String,pub change:&'static str,pub baseline_revision:Option<u64>,pub candidate_revision:Option<u64>}
#[derive(Serialize)]pub struct MemoryIssue{pub code:&'static str,pub memory_id:Option<String>,pub detail:String}
#[derive(Serialize)]pub struct MemoryResult{pub candidates:Vec<MemoryCandidate>,pub duplicates:Vec<MemoryDuplicate>,pub revision_changes:Vec<RevisionChange>,pub expiration_candidates:Vec<String>,pub issues:Vec<MemoryIssue>,pub index_size:usize,pub receipt_sha256:String,pub engine:&'static str,pub owner_domain:&'static str,pub receipt_version:u32}
fn normalize(text:&str)->String{text.to_lowercase().split_whitespace().collect::<Vec<_>>().join(" ")}
fn ngrams(text:&str,n:usize)->BTreeSet<String>{let chars:Vec<char>=normalize(text).chars().collect();if chars.is_empty(){return BTreeSet::new()}let width=n.max(1).min(8);if chars.len()<=width{return [chars.iter().collect()].into_iter().collect()}let mut out=BTreeSet::new();for i in 0..=chars.len()-width{out.insert(chars[i..i+width].iter().collect());}out}
fn similarity(a:&BTreeSet<String>,b:&BTreeSet<String>)->f64{if a.is_empty()&&b.is_empty(){return 1.0}let intersection=a.intersection(b).count()as f64;let union=a.union(b).count()as f64;if union==0.0{0.0}else{intersection/union}}
fn canonical_hash(record:&MemoryRecord)->String{let value=serde_json::json!({"id":record.id,"text":normalize(&record.text),"revision":record.revision,"created_at":record.created_at,"updated_at":record.updated_at,"importance":record.importance,"expires_at":record.expires_at});Sha256::digest(serde_json::to_vec(&value).unwrap_or_default()).iter().map(|b|format!("{b:02x}")).collect()}
fn decay(record:&MemoryRecord,now:u64,half:u64)->f64{if half==0{return 1.0}let age=now.saturating_sub(record.updated_at.max(record.created_at))as f64;(0.5f64).powf(age/half as f64)}
pub fn search_json(source:&str)->Result<String,String>{let r:MemoryRequest=serde_json::from_str(source).map_err(|e|format!("MEMORY_REQUEST_JSON:{e}"))?;if r.records.len()>500_000{return Err("MEMORY_RECORD_LIMIT".into())}let now=if r.now==0{1}else{r.now};let n=if r.ngram_size==0{3}else{r.ngram_size};let limit=if r.limit==0{50}else{r.limit.min(1000)};let threshold=if r.duplicate_threshold<=0.0{0.92}else{r.duplicate_threshold.min(1.0)};let half=if r.half_life_ms==0{30*24*60*60*1000}else{r.half_life_ms};let available:BTreeSet<_>=r.available_receipt_ids.into_iter().collect();let mut issues=Vec::new();for receipt in r.required_receipt_ids{if !available.contains(&receipt){issues.push(MemoryIssue{code:"MEMORY_RECEIPT_MISSING",memory_id:None,detail:receipt});}}let mut ids=BTreeSet::new();let mut prepared=Vec::new();let mut expiration=Vec::new();for record in &r.records{if record.id.trim().is_empty(){issues.push(MemoryIssue{code:"MEMORY_ID_REQUIRED",memory_id:None,detail:"empty id".into()});continue}if !ids.insert(record.id.clone()){issues.push(MemoryIssue{code:"MEMORY_ID_DUPLICATE",memory_id:Some(record.id.clone()),detail:"duplicate id".into()});continue}let actual=canonical_hash(record);if !record.content_sha256.is_empty()&&record.content_sha256!=actual{issues.push(MemoryIssue{code:"MEMORY_HASH_MISMATCH",memory_id:Some(record.id.clone()),detail:actual.clone()});}if record.revision==0{issues.push(MemoryIssue{code:"MEMORY_REVISION_INVALID",memory_id:Some(record.id.clone()),detail:"revision must be positive".into()});}if record.expires_at.map(|v|v<=now).unwrap_or(false){expiration.push(record.id.clone());}prepared.push((record,ngrams(&record.text,n),actual));}let query=ngrams(&r.query,n);let mut candidates=Vec::new();for(record,index,_)in &prepared{let sim=similarity(&query,index);let decayed=sim*decay(record,now,half)*(0.5+record.importance.max(0.0).min(1.0)*0.5);if sim>0.0{candidates.push(MemoryCandidate{id:record.id.clone(),similarity:sim,decayed_score:decayed,importance:record.importance,revision:record.revision});}}candidates.sort_by(|a,b|b.decayed_score.partial_cmp(&a.decayed_score).unwrap_or(std::cmp::Ordering::Equal).then_with(||b.importance.partial_cmp(&a.importance).unwrap_or(std::cmp::Ordering::Equal)).then_with(||b.revision.cmp(&a.revision)).then_with(||a.id.cmp(&b.id)));candidates.truncate(limit);let mut duplicates=Vec::new();for i in 0..prepared.len(){for j in i+1..prepared.len(){let sim=similarity(&prepared[i].1,&prepared[j].1);if sim>=threshold{duplicates.push(MemoryDuplicate{left_id:prepared[i].0.id.clone(),right_id:prepared[j].0.id.clone(),similarity:sim});}}}let baseline:BTreeMap<_,_>=r.baseline_records.into_iter().map(|v|(v.id,v)).collect();let current:BTreeMap<_,_>=r.records.iter().cloned().map(|v|(v.id.clone(),v)).collect();let mut revision_changes=Vec::new();for(id,record)in &current{match baseline.get(id){None=>revision_changes.push(RevisionChange{id:id.clone(),change:"ADDED",baseline_revision:None,candidate_revision:Some(record.revision)}),Some(old)if old.revision!=record.revision||canonical_hash(old)!=canonical_hash(record)=>revision_changes.push(RevisionChange{id:id.clone(),change:"UPDATED",baseline_revision:Some(old.revision),candidate_revision:Some(record.revision)}),_=>{}}}for(id,old)in &baseline{if !current.contains_key(id){revision_changes.push(RevisionChange{id:id.clone(),change:"REMOVED",baseline_revision:Some(old.revision),candidate_revision:None});}}let receipt_value=serde_json::json!({"candidate_ids":candidates.iter().map(|x|&x.id).collect::<Vec<_>>(),"duplicate_count":duplicates.len(),"revision_changes":revision_changes.iter().map(|x|(&x.id,x.change)).collect::<Vec<_>>(),"expiration":expiration,"issues":issues.iter().map(|x|(&x.code,&x.memory_id,&x.detail)).collect::<Vec<_>>()});let receipt_sha256=Sha256::digest(serde_json::to_vec(&receipt_value).unwrap_or_default()).iter().map(|b|format!("{b:02x}")).collect();let result=MemoryResult{candidates,duplicates,revision_changes,expiration_candidates:expiration,issues,index_size:prepared.iter().map(|x|x.1.len()).sum(),receipt_sha256,engine:"RUST",owner_domain:"memory",receipt_version:1};serde_json::to_string(&result).map_err(|e|format!("MEMORY_RESULT_JSON:{e}"))}

#[cfg(test)]
mod tests { use super::*;
 #[test] fn search_is_deterministic(){let x=r#"{"records":[{"id":"M1","text":"hello world","revision":1}],"query":"hello","now":1}"#;assert_eq!(search_json(x).unwrap(),search_json(x).unwrap());}
 #[test] fn invalid_revision_is_reported(){let x=r#"{"records":[{"id":"M1","text":"x","revision":0}],"query":"x","now":1}"#;assert!(search_json(x).unwrap().contains("MEMORY_REVISION_INVALID"));}
}
